INSERT INTO historia_idioma (hiid_titulo, hiid_legenda_imagem, hiid_texto, hist_id, idio_id) VALUES
('Iara: a Mãe da Água', 'Uma sereia de longos cabelos negros sentada sobre uma pedra, em meio às águas de um rio e à beleza d', 'Iara, uma jovem e encantadora guerreira, era filha do Pajé da aldeia. Forte, inteligente e de canto único, vivia sendo elogiada pelo pai.\r\n\r\nSeus dois irmãos tinham muita inveja. Juntos, planejaram dar um fim à filha do Pajé. Ao frio da noite e à luz da Lua, eles a atacaram de surpresa! Mas a jovem era uma excelente guerreira e percebeu.\r\n\r\nFuriosa e impiedosa, ela lutou com os irmãos. Ao perceber que havia matado os filhos do Pajé, Iara fugiu para a mata temendo ser castigada. Até que foi encontrada por guerreiros da aldeia e, às ordens do pai, foi jogada no rio.\r\n\r\nAs águas a abraçaram e ela afundou, afundou. Iara achava que sua vida tinha chegado ao fim. Mas, de repente, sentiu que subia. Alguns peixes estavam levando Iara para a superfície!\r\n\r\nEm um ato de pena e compaixão da Lua, Iara foi transformada em uma criatura meio peixe, meio mulher.\r\n\r\nAgora, vivia no rio. Ali, todas as tardes, cantava. Seu canto seduzia pescadores, guerreiros desavisados. Enfeitiçados pela criatura, entravam no rio, de onde nunca mais saíam.', 3, 1),
('Iara: la Madre del Agua', 'Una sirena de largos cabellos negros sentada sobre una piedra, en medio de las aguas de un río y la', 'Iara, una joven y encantadora guerrera, era hija del chamán de la aldea. Su padre constantemente la alababa por su fuerza, inteligencia y canto único.\r\n\r\nSus dos hermanos le tenían mucha envidia y, juntos, planearon acabar con la vida de la muchacha. ¡En una noche fría y oscura, le tendieron una emboscada! Pero la joven, al ser una excelente guerrera, se dio cuenta rápidamente.\r\n\r\nLuchó con gran fuerza y valentía contra sus hermanos. Al percatarse de que los había matado, Iara huyó hacia la selva por temor a ser castigada por el chamán. Tiempo después, los guerreros de la aldea la atraparon y, por orden de su padre, la arrojaron al río.\r\n\r\nLas aguas la envolvieron y ella se hundió cada vez más profundo. Iara creyó que su vida había acabado allí, pero, de repente, sintió que ascendía. ¡Unos peces la llevaban hacia la superficie!\r\n\r\nEn un acto de piedad y compasión, la Luna convirtió a Iara en una criatura mitad pez y mitad mujer. Así, podría vivir tranquila en el río.\r\n\r\nDesde entonces, vivió en el agua y, cada tarde, entonaba sus cantos. Su voz seducía a los pescadores y a los guerreros desprevenidos. Embrujados por la criatura, se adentraban en el río, de donde nunca más volverían a salir.', 3, 2);

